        /// <summary>
        /// This method is used to return vehicle passing details.
        /// </summary>
        /// <param name="aiSchoolId"></param>
        /// <param name="asFilter"></param>
        /// <param name="asSortExpression"></param>
        /// <param name="asSortDirection"></param>
        /// <param name="startRowIndex"></param>
        /// <param name="maximumRows"></param>
        /// <returns></returns>
        public List<VehiclePassingDetails> GetAllVehiclePassingDetails(int aiSchoolId, string asFilter, bool abShowOldRecord, string asSortExpression, string asSortDirection, int startRowIndex, int maximumRows)
        {
            if (asFilter == null)
                asFilter = "";

            if (String.IsNullOrEmpty(asSortExpression))
                asSortExpression = " ORDER BY ExpiryDate asc";
            else
            {
                asSortExpression = asSortExpression.Replace("ASC", string.Empty).Replace("DESC", string.Empty).Trim();
                asSortExpression = " ORDER BY " + asSortExpression + " " + asSortDirection;
            }
            List<VehiclePassingDetails> lstVehiclePassingDetails = moVehicleDetailsDC.GetAllVehiclePassingDetails(aiSchoolId, asFilter, abShowOldRecord, asSortExpression, startRowIndex, (startRowIndex + maximumRows));

            if (lstVehiclePassingDetails.Count > 0)
                miTotalRows = lstVehiclePassingDetails[0].TotalRows;
            else
                miTotalRows = 0;

            return lstVehiclePassingDetails;
        }

